70	/**
71	 * @author Vitaliy Fedoriv
72	 */
73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
83	    private static final int MAX_OWNERS_PER_CITY = 50;
84	
85	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
86	    private static final int MAX_OWNERS_PER_DAY = 100;
87	
88	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
89	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
90	
91	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
92	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
93	
94	    /**
95	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
96	     * create with an already-seen key returns the original owner instead of creating a duplicate.
97	     */
98	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
99	
100	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
101	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
102	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
103	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    private final TelephoneNormalizer telephoneNormalizer;
114	
115	    private final AddressNormalizer addressNormalizer;
116	
117	    private final EmailNormalizer emailNormalizer;
118	
119	    private final IdentityKeyResolver identityKeyResolver;
120	
121	    private final HouseholdResolver householdResolver;
122	
123	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
124	    private final HttpServletRequest request;
125	
126	    public OwnerRestControllerV1(ClinicService clinicService,
127	                                 OwnerMapper ownerMapper,
128	                                 PetMapper petMapper,
129	                                 VisitMapper visitMapper,
130	                                 TelephoneNormalizer telephoneNormalizer,
131	                                 AddressNormalizer addressNormalizer,
132	                                 EmailNormalizer emailNormalizer,
133	                                 IdentityKeyResolver identityKeyResolver,
134	                                 HouseholdResolver householdResolver,
135	                                 HttpServletRequest request) {
136	        this.clinicService = clinicService;
137	        this.ownerMapper = ownerMapper;
138	        this.petMapper = petMapper;
139	        this.visitMapper = visitMapper;
140	        this.telephoneNormalizer = telephoneNormalizer;
141	        this.addressNormalizer = addressNormalizer;
142	        this.emailNormalizer = emailNormalizer;
143	        this.identityKeyResolver = identityKeyResolver;
144	        this.householdResolver = householdResolver;
145	        this.request = request;
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
151	        Collection<Owner> owners;
152	        if (lastName != null) {
153	            owners = this.clinicService.findOwnerByLastName(lastName);
154	        } else {
155	            owners = this.clinicService.findAllOwners();
156	        }
157	        if (owners.isEmpty()) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        owners.forEach(this::populateHouseholdMemberCount);
161	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
162	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        populateHouseholdMemberCount(owner);
173	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    /**
177	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
178	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
179	     * by the mapper alone.
180	     *
181	     * @param owner the owner to map
182	     * @return the owner DTO carrying its identity key
183	     */
184	    private OwnerDto toOwnerDto(Owner owner) {
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
187	        return ownerDto;
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Transactional
192	    @Override
193	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
194	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
195	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
196	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
197	            if (replay != null) {
198	                return replay;
199	            }
200	        }
201	        Owner owner = createOwner(ownerFieldsDto);
202	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
203	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
204	        }
205	        return createdOwnerResponse(owner);
206	    }
207	
208	    /**
209	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
210	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
211	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
212	     * normally.
213	     *
214	     * @param idempotencyKey the client-supplied idempotency key from the request header
215	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
216	     */
217	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
218	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
219	        if (existingId == null) {
220	            return null;
221	        }
222	        Owner owner = this.clinicService.findOwnerById(existingId);
223	        if (owner == null) {
224	            return null;
225	        }
226	        populateHouseholdMemberCount(owner);
227	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
228	    }
229	
230	    /**
231	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
232	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
233	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guards then run against those derived
234	     * fields (see {@link #requireUniqueIdentity} and {@link #requireHouseholdNotDuplicate}) before the soft-duplicate
235	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
236	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
237	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
238	     *
239	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
240	     * @return the newly created, persisted owner
241	     */
242	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
243	        normalizeAndValidate(ownerFieldsDto);
244	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
245	        populateDerivedFields(owner, ownerFieldsDto);
246	        requireUniqueIdentity(owner);
247	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
248	        flagPossibleDuplicate(owner, ownerFieldsDto);
249	        this.clinicService.saveOwner(owner);
250	        populateHouseholdMemberCount(owner);
251	        auditOwnerCreated(owner);
252	        return owner;
253	    }
254	
255	    /**
256	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
257	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
258	     * canonical URL.
259	     *
260	     * @param owner the newly created, persisted owner
261	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
262	     */
263	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
264	        OwnerDto ownerDto = toOwnerDto(owner);
265	        HttpHeaders headers = new HttpHeaders();
266	        headers.setLocation(UriComponentsBuilder.newInstance()
267	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
268	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
269	    }
270	
271	    /**
272	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
273	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
274	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
275	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
276	     * {@link FiscalYearResolver#fiscalYear}).
277	     *
278	     * @param owner the newly created, persisted owner, with all its derived fields already in place
279	     */
280	    private void auditOwnerCreated(Owner owner) {
281	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
282	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
283	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
284	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()),
285	            owner.getCustomerCode() + "-M" + String.format("%02d",
286	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
287	    }
288	
289	    /**
290	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
291	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
292	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
293	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
294	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
295	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
296	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
297	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
298	     *
299	     * @param owner          the newly mapped owner about to be saved
300	     * @param ownerFieldsDto the incoming owner payload
301	     */
302	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
303	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
304	        owner.setNamesakeCount(countNamesakes(owner));
305	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
306	        assignHouseholdId(owner);
307	    }
308	
309	    /**
310	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
311	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
312	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
313	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
314	     * that predate this create; distinct owners therefore always receive distinct customer codes.
315	     *
316	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
317	     * @return the de-duplicated customer code, unique across all existing owners
318	     */
319	    private String deriveUniqueCustomerCode(Owner owner) {
320	        String base = identityKeyResolver.deriveCustomerCode(owner);
321	        Collection<Owner> existing = this.clinicService.findAllOwners();
322	        String candidate = base;
323	        int n = 2;
324	        while (isCustomerCodeInUse(candidate, existing)) {
325	            candidate = base + "-" + n;
326	            n++;
327	        }
328	        return candidate;
329	    }
330	
331	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
332	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
333	    }
334	
335	    /**
336	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
337	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
338	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
339	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
340	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
341	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
342	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
343	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
344	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
345	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
346	     * assigned (see {@link #requireUniqueIdentity}).
347	     *
348	     * @param ownerFieldsDto the incoming owner payload, mutated in place
349	     * @throws MissingOwnerFieldsException if any required field is missing or blank
350	     */
351	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
352	        normalizeAddress(ownerFieldsDto);
353	        validateRequiredFields(ownerFieldsDto);
354	        validatePostcode(ownerFieldsDto);
355	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
356	        ownerFieldsDto.setTelephone(telephone);
357	        requireCityHasCapacity(ownerFieldsDto.getCity());
358	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
359	        ownerFieldsDto.setRegistrationDate(registrationDate);
360	        requireDailyLimitNotReached(registrationDate);
361	        normalizeEmail(ownerFieldsDto);
362	    }
363	
364	    /**
365	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
366	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
367	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
368	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
369	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
370	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
371	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
372	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
373	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
374	     *
375	     * @param ownerFieldsDto the incoming owner payload, mutated in place
376	     */
377	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
378	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
379	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
380	        if (!line1.isEmpty()) {
381	            ownerFieldsDto.setAddressLine1(line1);
382	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
383	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
384	        }
385	        else {
386	            ownerFieldsDto.setAddressLine1(null);
387	            ownerFieldsDto.setAddressLine2(null);
388	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
389	        }
390	    }
391	
392	    /**
393	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
394	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
395	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
396	     * place so the caller can map and save it directly.
397	     *
398	     * @param ownerFieldsDto the incoming owner payload, mutated in place
399	     */
400	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
401	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
402	    }
403	
404	    /**
405	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
406	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
407	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
408	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
409	     * date is rejected.
410	     *
411	     * @param ownerFieldsDto the incoming owner payload
412	     * @return the effective registration date rolled forward onto a business day
413	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
414	     */
415	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
416	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
417	        if (effective == null) {
418	            effective = LocalDate.now();
419	        }
420	        else if (effective.isAfter(LocalDate.now())) {
421	            throw new FutureRegistrationDateException(
422	                "the registration date must not be later than the current server date");
423	        }
424	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
425	            || PUBLIC_HOLIDAYS.contains(effective)) {
426	            effective = effective.plusDays(1);
427	        }
428	        return effective;
429	    }
430	
431	    /**
432	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
433	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
434	     * further owner may be created for that day.
435	     *
436	     * @param registrationDate the adjusted business-day registration date of the owner being created
437	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
438	     */
439	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
440	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
441	            throw new DailyOwnerLimitExceededException(
442	                "the maximum number of owners for today has already been reached");
443	        }
444	    }
445	
446	    /**
447	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
448	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
449	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
450	     * warning threshold) so both express the same per-day count in one place.
451	     *
452	     * @param registrationDate the adjusted business-day registration date to count owners for
453	     * @return the number of existing owners registered on that day
454	     */
455	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
456	        return this.clinicService.findAllOwners().stream()
457	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
458	            .count();
459	    }
460	
461	    /**
462	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
463	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
464	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
465	     * reflects only owners that predate it.
466	     *
467	     * @param registrationDate the adjusted business-day registration date of the owner being created
468	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
469	     */
470	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
471	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
472	    }
473	
474	    /**
475	     * Counts how many existing owners already share the given owner's first and last name, compared
476	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
477	     * create; it is zero when the owner's name is unique.
478	     *
479	     * @param owner the newly mapped owner about to be saved
480	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
481	     */
482	    private int countNamesakes(Owner owner) {
483	        String firstName = owner.getFirstName();
484	        String lastName = owner.getLastName();
485	        return (int) this.clinicService.findAllOwners().stream()
486	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
487	                && lastName.equalsIgnoreCase(existing.getLastName()))
488	            .count();
489	    }
490	
491	    /**
492	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
493	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
494	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
495	     *
496	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
497	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
498	     * flat {@code address}.
499	     *
500	     * @param ownerFieldsDto the owner payload to validate
501	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
502	     */
503	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
504	        List<String> missingFields = new ArrayList<>();
505	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
506	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
507	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
508	        requireText(missingFields, "city", ownerFieldsDto.getCity());
509	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
510	        if (!missingFields.isEmpty()) {
511	            throw new MissingOwnerFieldsException(missingFields);
512	        }
513	    }
514	
515	    private void requireText(List<String> missingFields, String fieldName, String value) {
516	        if (value == null || value.isBlank()) {
517	            missingFields.add(fieldName);
518	        }
519	    }
520	
521	    /**
522	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
523	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
524	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
525	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
526	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
527	     *
528	     * @param ownerFieldsDto the incoming owner payload
529	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
530	     */
531	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
532	        String postcode = ownerFieldsDto.getPostcode();
533	        if (postcode == null) {
534	            return;
535	        }
536	        Region region = Region.forCity(ownerFieldsDto.getCity());
537	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
538	            throw new InvalidPostcodeException(
539	                "postcode " + postcode + " is not valid for the city's region " + region.name());
540	        }
541	    }
542	
543	    /**
544	     * Rejects creating an owner whose whole derived {@code identityKey} (see
545	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
546	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
547	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
548	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
549	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}). Owners that have been
550	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted
551	     * owner does not block the create.
552	     *
553	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
554	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
555	     */
556	    private void requireUniqueIdentity(Owner owner) {
557	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
558	        boolean inUse = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> !existing.isDeleted())
560	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
561	        if (inUse) {
562	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
563	        }
564	    }
565	
566	    /**
567	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
568	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
569	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
570	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
571	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
572	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
573	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
574	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
575	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
576	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
577	     *
578	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
579	     * @param ownerFieldsDto the incoming owner payload
580	     */
581	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
582	        owner.setPossibleDuplicate(false);
583	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
584	            return;
585	        }
586	        String postcode = owner.getPostcode();
587	        if (postcode == null || postcode.isBlank()) {
588	            return;
589	        }
590	        String lastName = owner.getLastName();
591	        String telephone = owner.getTelephone();
592	        for (Owner existing : this.clinicService.findAllOwners()) {
593	            if (lastName.equalsIgnoreCase(existing.getLastName())
594	                && postcode.equals(existing.getPostcode())
595	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
596	                owner.setPossibleDuplicate(true);
597	                owner.setPossibleDuplicateOf(existing.getId());
598	                return;
599	            }
600	        }
601	    }
602	
603	    /**
604	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
605	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
606	     *
607	     * @param city the city of the owner being created
608	     * @throws OwnerCityFullException if the city already contains 50 or more owners
609	     */
610	    private void requireCityHasCapacity(String city) {
611	        long cityOwners = this.clinicService.findAllOwners().stream()
612	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
613	            .count();
614	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
615	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
616	        }
617	    }
618	
619	    /**
620	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
621	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
622	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
623	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
624	     * such owners never match one another as a household.
625	     *
626	     * @param owner the newly mapped owner about to be saved
627	     */
628	    private void assignHouseholdId(Owner owner) {
629	        String postcode = owner.getPostcode();
630	        if (postcode == null || postcode.isBlank()) {
631	            owner.setHouseholdId(null);
632	            return;
633	        }
634	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
635	    }
636	
637	    /**
638	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
639	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
640	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
641	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
642	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
643	     * without a postcode) can never be a household duplicate. Owners that have been soft-deleted (see
644	     * {@link #deleteOwner}) are ignored, so a household whose only member has been deleted does not block the create.
645	     *
646	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
647	     * @param ownerFieldsDto the incoming owner payload
648	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
649	     *                                 declare {@code sharesHousehold}
650	     */
651	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
652	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
653	            return;
654	        }
655	        String householdId = owner.getHouseholdId();
656	        if (householdId == null) {
657	            return;
658	        }
659	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
660	            .filter(existing -> !existing.isDeleted())
661	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
662	        if (sharedByExisting) {
663	            throw new DuplicateOwnerException("an owner in the same household already exists");
664	        }
665	    }
666	
667	    /**
668	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
669	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
670	     * household is counted as a household of one.
671	     *
672	     * @param owner the owner whose household size should be resolved
673	     */
674	    private void populateHouseholdMemberCount(Owner owner) {
675	        String householdId = owner.getHouseholdId();
676	        if (householdId == null) {
677	            owner.setHouseholdMemberCount(1);
678	            return;
679	        }
680	        long members = this.clinicService.findAllOwners().stream()
681	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
682	            .count();
683	        owner.setHouseholdMemberCount((int) members);
684	    }
685	
686	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
687	    @Override
688	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
689	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
690	        if (currentOwner == null) {
691	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
692	        }
693	        validatePostcode(ownerFieldsDto);
694	        currentOwner.setAddress(ownerFieldsDto.getAddress());
695	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
696	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
697	        currentOwner.setCity(ownerFieldsDto.getCity());
698	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
699	        currentOwner.setLastName(ownerFieldsDto.getLastName());
700	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
701	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
702	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
703	        this.clinicService.saveOwner(currentOwner);
704	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
705	    }
706	
707	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
708	    @Transactional
709	    @Override
710	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
711	        Owner owner = this.clinicService.findOwnerById(ownerId);
712	        if (owner == null) {
713	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
714	        }
715	        owner.setDeleted(true);
716	        this.clinicService.saveOwner(owner);
717	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
718	    }
719	
720	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
721	    @Override
722	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
723	        Owner owner = this.clinicService.findOwnerById(ownerId);
724	        if (owner == null) {
725	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
726	        }
727	        HttpHeaders headers = new HttpHeaders();
728	        Pet pet = petMapper.toPet(petFieldsDto);
729	        owner.setId(ownerId);
730	        pet.setOwner(owner);
731	        pet.getType().setName(null);
732	        this.clinicService.savePet(pet);
733	        PetDto petDto = petMapper.toPetDto(pet);
734	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
735	            .buildAndExpand(pet.getId()).toUri());
736	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
737	    }
738	
739	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
740	    @Override
741	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
742	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
743	        if (currentOwner != null) {
744	            Pet currentPet = this.clinicService.findPetById(petId);
745	            if (currentPet != null) {
746	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
747	                currentPet.setName(petFieldsDto.getName());
748	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
749	                this.clinicService.savePet(currentPet);
750	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
751	            }
752	        }
753	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
754	    }
755	
756	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
757	    @Override
758	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
759	        HttpHeaders headers = new HttpHeaders();
760	        Visit visit = visitMapper.toVisit(visitFieldsDto);
761	        Pet pet = new Pet();
762	        pet.setId(petId);
763	        visit.setPet(pet);
764	        this.clinicService.saveVisit(visit);
765	        VisitDto visitDto = visitMapper.toVisitDto(visit);
766	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
767	            .buildAndExpand(visit.getId()).toUri());
768	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
769	    }
770	
771	
772	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
773	    @Override
774	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
775	        Owner owner = this.clinicService.findOwnerById(ownerId);
776	        if (owner != null) {
777	            Pet pet = owner.getPet(petId);
778	            if (pet != null) {
779	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
780	            }
781	        }
782	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
783	    }
784	}
